    <label>Overlay Color<input value={(editing||f).overlay_color||'rgba(0,0,0,0.38)'} onChange={e=>{const setter=editing?setEditing:setF;setter({...((editing||f)),overlay_color:e.target.value})}} placeholder="rgba(0,0,0,.38)"/></label>
